// 严格分离结构/军籍与人物技艺；未知过去参与者或无真实工程头时拒绝，不产生兼容默认值。
#include "military_siege_engineering_source.hpp"
#include "military_officer_source.hpp"
#include "military_roster_history.hpp"
#include <algorithm>
#include <charconv>
#include <limits>
namespace hanmo::resident {
namespace {
template<class T>const T* find(const std::vector<T>& rows,const StableId& id){for(const auto& row:rows)if(row.id==id)return &row;return nullptr;}
bool same_identity(const WorldIdentity& a,const WorldIdentity& b){return a.world_id==b.world_id&&a.execution_epoch==b.execution_epoch&&a.revision==b.revision&&a.tick==b.tick;}
bool same_source(const MilitaryUnitCommandSource& a,const MilitaryUnitCommandSource& b){return a.kind==b.kind&&a.id==b.id;}
Outcome<Integer> limit(const CommonStore& c,const DynamicStepInput* phase){if(!phase)return {true,c.tick(),{}};if(phase->from_tick!=c.tick()||phase->from_tick<0||phase->from_tick==std::numeric_limits<Integer>::max()||phase->to_tick!=phase->from_tick+1)return {false,{},common_failure("MilitarySiegeEngineeringPhaseMismatch").error};return {true,phase->to_tick,{}};}
Status ordered_sources(const CommonStore& c,const std::vector<StableId>& ids,const StableId& boundary){const auto& order=c.state().facts.order();auto end=boundary.empty()?order.end():std::find(order.begin(),order.end(),boundary);if(!boundary.empty()&&end==order.end())return common_failure("MilitarySiegeEngineeringBoundaryMissing",boundary);auto prior=order.end();for(const auto& id:ids){auto at=std::find(order.begin(),order.end(),id);auto* head=c.state().facts.find(id);if(!head||head->id!=id||at==order.end()||at>=end||(prior!=order.end()&&at<=prior))return common_failure("MilitarySiegeEngineeringSourceOrder",id);prior=at;}return common_success();}
Status actual_header(const CommonStore& c,const MilitarySiegeEngineeringPreparation& p,Integer upper){auto valid=validate_military_siege_engineering_preparation_shape(p);if(!valid.ok)return valid;const StableId prefix=StableId{military_siege_engineering_fact_prefix}+":";if(p.id.rfind(prefix,0)!=0)return common_failure("MilitarySiegeEngineeringFactRequired",p.id);Integer n=0;auto tail=p.id.substr(prefix.size());auto parsed=std::from_chars(tail.data(),tail.data()+tail.size(),n);auto* head=c.state().facts.find(p.id);if(parsed.ec!=std::errc{}||parsed.ptr!=tail.data()+tail.size()||n<1||std::to_string(n)!=tail||n>=c.state().next_instance_id||p.to_tick>upper||!head||head->id!=p.id||head->kind!=military_siege_engineering_fact_kind||head->domain!="military")return common_failure("MilitarySiegeEngineeringFactRequired",p.id);return common_success();}
}
static Outcome<MilitarySiegeEngineeringPreparation> preview_preparation(const CommonStore& c,const MilitaryState& s,const MilitaryCatalog& cat,const SiegeRecord& siege,const MilitarySiegeEngineeringSkillRead& reader,const DynamicStepInput& phase,Integer skill_observation_tick){
 auto upper=limit(c,&phase);if(!upper.ok)return {false,{},upper.error};if(siege.phase!="active"||siege.last_tick!=phase.from_tick||siege.round<1||!find(s.sieges,siege.id))return {false,{},common_failure("MilitarySiegeEngineeringActiveSiegeRequired",siege.id).error};MilitarySiegeEngineeringPreparation out;out.id="uncommitted";out.siege_id=siege.id;out.topology_id=siege.topology_id;out.from_tick=phase.from_tick;out.to_tick=phase.to_tick;out.round=siege.round;
 std::vector<StableId> ids;for(const auto& node:siege.unit_nodes)ids.push_back(node.first);std::sort(ids.begin(),ids.end());if(std::adjacent_find(ids.begin(),ids.end())!=ids.end())return {false,{},common_failure("MilitarySiegeEngineeringUnitShape",siege.id).error};
 for(const auto& id:ids){const auto* unit=find(s.military_units,id);if(!unit||!std::any_of(siege.armies.begin(),siege.armies.end(),[&](const auto& army){return army.first==unit->army_id;}))return {false,{},common_failure("MilitarySiegeEngineeringArmyRequired",id).error};auto command=query_military_unit_command_source(c,s,cat,id,phase);if(!command.ok)return {false,{},command.error};if(command.value.commander_actor_id!=unit->commander_actor_id)return {false,{},common_failure("MilitarySiegeEngineeringCommandMismatch",id).error};auto read=reader.current_siege_engineering_skill(unit->commander_actor_id);if(!read.ok)return {false,{},read.error};const auto& q=read.value;
  if(!same_identity(q.source_identity,c.state().identity)||q.actor_id!=unit->commander_actor_id||q.skill_id!="fortification"||q.observed_tick!=skill_observation_tick||!q.before_fact_id.empty())return {false,{},common_failure("MilitarySiegeEngineeringSkillMismatch",id).error};auto checked=ordered_sources(c,q.causal_fact_ids,{});if(!checked.ok)return {false,{},checked.error};MilitarySiegeEngineeringUnit row;row.unit_id=id;row.army_id=unit->army_id;row.commander_actor_id=unit->commander_actor_id;row.authored_actor_id=q.authored_actor_id;row.command_source=command.value.command_source;row.fit_count=static_cast<Integer>(unit->fit.size());row.experience=q.experience;row.level=q.level;row.causal_fact_ids=q.causal_fact_ids;out.units.push_back(std::move(row));
 }
 auto checked=validate_military_siege_engineering_preparation_shape(out);return checked.ok?Outcome<MilitarySiegeEngineeringPreparation>{true,std::move(out),{}}:Outcome<MilitarySiegeEngineeringPreparation>{false,{},checked.error};
}
// 真阶段准备与稳定报价各固定观察截面，不对外提供任意tick选择。
Outcome<MilitarySiegeEngineeringPreparation> preview_military_siege_engineering_preparation(const CommonStore& c,const MilitaryState& s,const MilitaryCatalog& cat,const SiegeRecord& siege,const MilitarySiegeEngineeringSkillRead& reader,const DynamicStepInput& phase){return preview_preparation(c,s,cat,siege,reader,phase,phase.to_tick);}
Outcome<MilitarySiegeEngineeringPreparation> preview_current_military_siege_engineering_preparation(const CommonStore& c,const MilitaryState& s,const MilitaryCatalog& cat,const SiegeRecord& siege,const MilitarySiegeEngineeringSkillRead& reader){if(c.tick()<0||c.tick()==std::numeric_limits<Integer>::max())return {false,{},common_failure("MilitarySiegeEngineeringPhaseMismatch").error};DynamicStepInput next;next.from_tick=c.tick();next.to_tick=c.tick()+1;return preview_preparation(c,s,cat,siege,reader,next,c.tick());}
Status validate_military_siege_engineering_bindings(const CommonStore& c,const MilitaryState& s,const MilitaryCatalog& cat,const MilitarySiegeEngineeringPreparation& p,const MilitarySiegeParticipationRead& reader,const DynamicStepInput* phase,const PopulationMilitaryState* population,const PopulationMilitaryCatalog* population_catalog){
 auto upper=limit(c,phase);if(!upper.ok)return {false,{},upper.error};auto valid=actual_header(c,p,upper.value);if(!valid.ok)return valid;auto participation=reader.participation_before_engineering(p.siege_id,p.id);if(!participation.ok)return {false,{},participation.error};const auto& q=participation.value;std::vector<StableId> ids;for(const auto& u:p.units)ids.push_back(u.unit_id);
 if(!same_identity(q.source_identity,c.state().identity)||q.siege_id!=p.siege_id||q.topology_id!=p.topology_id||q.before_fact_id!=p.id||q.observed_tick!=p.to_tick||q.round!=p.round||q.unit_ids!=ids||q.lifecycle_source_ids.empty())return common_failure("MilitarySiegeEngineeringParticipationRequired",p.id);valid=ordered_sources(c,q.lifecycle_source_ids,p.id);if(!valid.ok)return valid;
 for(const auto& source:q.lifecycle_source_ids){const auto* head=c.state().facts.find(source);if(source.rfind("military_siege_lifecycle:",0)!=0||!head||head->domain!="military"||(head->kind!="military_siege_created"&&head->kind!="military_siege_joined"&&head->kind!="military_siege_advanced"&&head->kind!="military_siege_battle_finished"&&head->kind!="military_siege_strategic"&&head->kind!="military_siege_terminated"&&head->kind!="military_siege_closed"&&head->kind!="military_siege_integrated"&&head->kind!="military_siege_departed"))return common_failure("MilitarySiegeEngineeringParticipationSourceMismatch",source);}
 auto rosters=phase?military_rosters_before(c,s,cat,ids,p.to_tick,p.id,*phase,population,population_catalog):military_rosters_before(c,s,cat,ids,p.to_tick,p.id,population,population_catalog);if(!rosters.ok)return {false,{},rosters.error};
 for(const auto& u:p.units){const auto* original=find(rosters.value,u.unit_id);if(!original||original->army_id!=u.army_id||original->commander_actor_id!=u.commander_actor_id||Integer(original->fit.size())!=u.fit_count)return common_failure("MilitarySiegeEngineeringRosterMismatch",u.unit_id);auto command=phase?query_military_unit_command_source_before(c,s,cat,u.unit_id,p.id,*phase):query_military_unit_command_source_before(c,s,cat,u.unit_id,p.id);if(!command.ok)return {false,{},command.error};if(command.value.commander_actor_id!=u.commander_actor_id||!same_source(command.value.command_source,u.command_source))return common_failure("MilitarySiegeEngineeringCommandMismatch",u.unit_id);valid=ordered_sources(c,u.causal_fact_ids,p.id);if(!valid.ok)return valid;}
 return common_success();
}
Status validate_military_siege_engineering_actor_sources(const CommonStore& c,const MilitarySiegeEngineeringPreparation& p,const MilitarySiegeEngineeringSkillRead& reader){auto valid=actual_header(c,p,c.tick());if(!valid.ok)return valid;for(const auto& u:p.units){auto read=reader.siege_engineering_skill_before_preparation(u.commander_actor_id,p.id);if(!read.ok)return {false,{},read.error};const auto& q=read.value;if(!same_identity(q.source_identity,c.state().identity)||q.actor_id!=u.commander_actor_id||q.skill_id!="fortification"||q.before_fact_id!=p.id||q.observed_tick!=p.to_tick||q.experience!=u.experience||q.level!=u.level||q.authored_actor_id!=u.authored_actor_id||q.causal_fact_ids!=u.causal_fact_ids)return common_failure("MilitarySiegeEngineeringSkillMismatch",u.unit_id);valid=ordered_sources(c,u.causal_fact_ids,p.id);if(!valid.ok)return valid;}return common_success();}
}
